(r, big) => {
  const n = big ? 50 : r.int(2, 5), N = n * n;
  const vals = Array.from({ length: N }, (_, i) => i + 1);
  const miss = r.int(1, N);
  let dup = r.int(1, N);
  while (dup === miss) dup = r.int(1, N);
  vals[miss - 1] = dup;
  const mixed = r.shuffle(vals), grid = [];
  for (let i = 0; i < n; i++) grid.push(mixed.slice(i * n, i * n + n));
  return [grid];
}

