function doubledAndAbsent(grid: number[][]): number[] {
  const N = grid.length * grid.length;
  const counts = new Array(N + 1).fill(0);
  for (const row of grid) for (const v of row) counts[v]++;
  let doubled = 0, missing = 0;
  for (let v = 1; v <= N; v++) {
    if (counts[v] === 2) doubled = v;
    else if (counts[v] === 0) missing = v;
  }
  return [doubled, missing];
}

