class Solution:
    def doubledAndAbsent(self, grid: List[List[int]]) -> List[int]:
        N = len(grid) * len(grid)
        counts = [0] * (N + 1)
        for row in grid:
            for v in row:
                counts[v] += 1
        doubled = missing = 0
        for v in range(1, N + 1):
            if counts[v] == 2:
                doubled = v
            elif counts[v] == 0:
                missing = v
        return [doubled, missing]

