function doubledAndAbsent(grid: number[][]): number[] {
  const N = grid.length * grid.length;
  let sum = 0, sq = 0;
  for (const row of grid) for (const v of row) { sum += v; sq += v * v; }
  const diff = sum - (N * (N + 1)) / 2;                       // doubled - missing
  const sqDiff = sq - (N * (N + 1) * (2 * N + 1)) / 6;        // doubled^2 - missing^2
  const total = sqDiff / diff;                                 // doubled + missing
  return [(total + diff) / 2, (total - diff) / 2];
}

